package store

// SecretColumns is the protected thing.
var SecretColumns = []string{"token"}

// Seal is the chokepoint: the one way a row leaves without its secrets.
func Seal(row map[string]string) map[string]string {
	out := map[string]string{}
	for k, v := range row {
		out[k] = v
	}
	for _, column := range SecretColumns {
		delete(out, column)
	}
	return out
}

